  return posts;
}

export function createPost(data: { title: string; content: string }): Post {
  const post: Post = {
    id: crypto.randomUUID(),
    title: data.title,
    content: data.content,
    createdAt: new Date(),
  };
  posts.unshift(post);
  return post;
}

