import { cache } from 'react';
import { getPosts } from '@/lib/posts';
import { createPost } from './actions';

const getPostsCached = cache(async () => {
  return getPosts();
});

export default function Home() {
  return (
    <main style={{ padding: '2rem' }}>
      <h1>Posts</h1>

      <section>
        <h2>Create Post</h2>
        <form action={createPost}>
          <div style={{ marginBottom: '1rem' }}>
            <label htmlFor="title" style={{ display: 'block', marginBottom: '0.25rem' }}>
              Title
            </label>
            <input
              type="text"
              id="title"
              name="title"
              required
              style={{ width: '100%', padding: '0.5rem' }}
            />
          </div>
          <div style={{ marginBottom: '1rem' }}>
            <label htmlFor="content" style={{ display: 'block', marginBottom: '0.25rem' }}>
              Content
            </label>
            <textarea
              id="content"
              name="content"
              required
              style={{ width: '100%', padding: '0.5rem', minHeight: '100px' }}
            />
          </div>
          <button type="submit" style={{ padding: '0.5rem 1rem' }}>
            Create Post
          </button>
        </form>
      </section>

      <section style={{ marginTop: '2rem' }}>
        <h2>Posts</h2>
        <PostsList />
      </section>
    </main>
  );
}

async function PostsList() {
  const posts = await getPostsCached();

  if (posts.length === 0) {
    return <p>No posts yet.</p>;
  }

  return (
    <ul style={{ listStyle: 'none', padding: 0 }}>
      {posts.map((post) => (
        <li key={post.id} style={{ padding: '1rem', border: '1px solid #ccc', marginBottom: '0.5rem' }}>
          <h3 style={{ margin: '0 0 0.5rem 0' }}>{post.title}</h3>
          <p style={{ margin: 0 }}>{post.content}</p>
          <small style={{ color: '#666' }}>
            {post.createdAt.toLocaleString()}
          </small>
        </li>
      ))}
    </ul>
  );
}

